      channel.volume,
      channel.meter,
      channel.controls.length,
    ]),
  ).toEqual([
    ["song", 0.8, 0.45, 4],
    ["stream", 0.8, null, 4],
    ["instants", 0.8, 0, 4],
    ["sceneInstant", 0.8, 0, 4],
    ["main", 1, 0.45, 0],
  ]);
