  press("audio: music change");
  expect(data("audio").songs).toBe(1);
  press("audio: add songs");
  expect(data("audio").songs).toBe(12);
  press("audio: music take");
  expect(data("audio").songs).toBe(1);
  press("audio: add songs");
  press("audio: cart search");
