      highRotation: true,
    },
    {
      id: "fixture-song-2",
      kind: "preset",
      artist: "Control Room",
      title: "No Repeat",
      coverUrl: "",
      audioUrl: "https://example.test/fixture-song-2.mp3",
      durationMs: 210_000,
    },
  ],
};

const consoleSongs: ProgramSongSequence = {
  ...playbackSequence,
  items: [
    ...playbackSequence.items,
    ...[
      "City Lights",
      "Late Summer",
      "Golden Hour",
      "After the Rain",
      "Midnight Signal",
      "Coastline",
      "Open Road",
      "Morning Blue",
      "Satellite",
